steps.stdout:
{
  "name": "pf-techack",
  "networks": {
    "model": {
      "name": "pf-techack_model",
      "ipam": {}
    },
    "target": {
      "name": "pf-techack_target",
      "ipam": {}
    }
  },
  "services": {
    "juice-shop": {
      "cpus": 1,
      "command": null,
      "entrypoint": null,
      "healthcheck": {
        "test": [
          "CMD",
          "node",
          "-e",
          "require('http').get('http://127.0.0.1:3000/',r=\u003e{r.resume();process.exit(r.statusCode===200?0:1)}).on('error',()=\u003eprocess.exit(1))"
        ],
        "timeout": "5s",
        "interval": "10s",
        "retries": 18,
        "start_period": "30s"
      },
      "image": "bkimminich/juice-shop:latest",
      "init": true,
      "mem_limit": "805306368",
      "networks": {
        "target": null
      },
      "ports": [
        {
          "mode": "ingress",
          "host_ip": "127.0.0.1",
          "target": 3000,
          "published": "3000",
          "protocol": "tcp"
        }
      ],
      "restart": "no",
      "security_opt": [
        "no-new-privileges:true"
      ]
    },
    "ollama": {
      "cpus": 3,
      "command": null,
      "entrypoint": null,
      "environment": {
        "LAB_MODEL": "qwen3:1.7b",
        "OLLAMA_CONTEXT_LENGTH": "2048",
        "OLLAMA_HOST": "0.0.0.0:11434",
        "OLLAMA_KEEP_ALIVE": "2m",
        "OLLAMA_MAX_LOADED_MODELS": "1",
        "OLLAMA_NO_CLOUD": "1",
        "OLLAMA_NUM_PARALLEL": "1"
      },
      "healthcheck": {
        "test": [
          "CMD",
          "ollama",
          "list"
        ],
        "timeout": "5s",
        "interval": "10s",
        "retries": 12,
        "start_period": "15s"
      },
      "image": "ollama/ollama:latest",
      "mem_limit": "3221225472",
      "networks": {
        "model": null
      },
      "ports": [
        {
          "mode": "ingress",
          "host_ip": "127.0.0.1",
          "target": 11434,
          "published": "11434",
          "protocol": "tcp"
        }
      ],
      "restart": "no",
      "volumes": [
        {
          "type": "volume",
          "source": "ollama-data",
          "target": "/root/.ollama",
          "volume": {}
        }
      ]
    },
    "tools": {
      "profiles": [
        "tools"
      ],
      "build": {
        "context": "/Users/luizmiguelmoraesberredo/Documents/INSPER/7-semestre/TecHack/pf-techack/docker/tools",
        "dockerfile": "Dockerfile"
      },
      "cap_drop": [
        "ALL"
      ],
      "command": [
        "python3",
        "--version"
      ],
      "entrypoint": null,
      "mem_limit": "268435456",
      "networks": {
        "target": null
      },
      "read_only": true,
      "security_opt": [
        "no-new-privileges:true"
      ],
      "tmpfs": [
        "/tmp"
      ]
    }
  },
  "volumes": {
    "ollama-data": {
      "name": "pf-techack_ollama-data"
    }
  }
}
